from lib import *
S = SS('f168')
R = J('f168'); z = R['zipf']; cap = R['cap']; dist = R['dist']; ttl = R['ttl']; rd = R['redis']
steps = [
    step(f"访问序列:20000 个请求落在 5000 个 key 上,服从 Zipf 分布(少数热点占大头):最热的 key 占 {z[0] * 100:.1f}%,前 100 个 key 占 {z[1] * 100:.1f}%,前 500 个占 {z[2] * 100:.1f}%。缓存容量(SimpleCache 的 threshold,超过就清理旧条目)对命中率的影响:100 → {cap['100'][0] * 100:.1f}%、500 → {cap['500'][0] * 100:.1f}%、2000 → {cap['2000'][0] * 100:.1f}%、5000(全部装得下)→ {cap['5000'][0] * 100:.1f}%。按「未命中 5 ms、命中 0.05 ms」算,平均耗时从 {cap['100'][1]:.2f} ms 降到 {cap['5000'][1]:.2f} ms。命中率提升不是线性的:前几百个热点贡献了大头,往后每多装一些收益递减;而且即使全装得下,第一次访问的未命中也无法避免,所以上限不是 100%。", b=bars([['容量 100', cap['100'][0] * 100, f"{cap['100'][0] * 100:.0f}%"], ['容量 500', cap['500'][0] * 100, f"{cap['500'][0] * 100:.0f}%"], ['容量 2000', cap['2000'][0] * 100, f"{cap['2000'][0] * 100:.0f}%"], ['容量 5000', cap['5000'][0] * 100, f"{cap['5000'][0] * 100:.0f}%"]], 100, done=[0, 1, 2, 3]), t=tl(S(1)), done=lidx(S(1), '       100 ', '       500 ', '      2000 ', '      5000 '), kv=KV([['容量 100 → 5000', f"{cap['100'][0] * 100:.0f}% → {cap['5000'][0] * 100:.0f}%"], ['平均耗时', f"{cap['100'][1]:.2f} → {cap['5000'][1]:.2f} ms"]], ['容量 100 → 5000'])),
    step(f"访问分布比容量更重要:同样容量 500,Zipf(有热点)命中率 {dist['Zipf(有热点)'] * 100:.1f}%,均匀随机访问只有 {dist['均匀随机'] * 100:.1f}%(容量只占 key 总数的 10%,命中率就约等于 10% 再减去冷启动)。key 的访问没有热点时,缓存几乎没用——先看访问分布,再决定要不要缓存。", t=tl(S(2)), done=lidx(S(2), 'Zipf'), mark=lidx(S(2), '均匀随机'), kv=KV([['有热点', f"{dist['Zipf(有热点)'] * 100:.0f}%"], ['均匀随机', f"{dist['均匀随机'] * 100:.0f}%"]], ['有热点'])),
    step(f"过期时间对命中率的影响(Zipf、容量足够,模拟时钟每个请求前进 1 ms,20000 个请求相当于 20 秒):TTL 1 秒及以下 {ttl['1 秒'] * 100:.1f}%、2 秒 {ttl['2 秒'] * 100:.1f}%、5 秒 {ttl['5 秒'] * 100:.1f}%、10 秒 {ttl['10 秒'] * 100:.1f}%、不过期 {ttl['不过期'] * 100:.1f}%。TTL 越短,同一个 key 被重新计算的次数越多;但 TTL 要和数据能容忍多久不新鲜匹配。另外一个细节:cachelib 的 SimpleCache 用 int(time()) + TTL 计算到期时间(源码如此),亚秒级的 TTL 没有意义——0.05、0.5、1 秒三个设置的命中率完全相同。", t=tl(S(3)), done=lidx(S(3), 'TTL 2 秒', 'TTL 5 秒', 'TTL 10 秒', '不过期'), mark=lidx(S(3), 'TTL 0.05', 'TTL 0.5', 'TTL 1 秒'), kv=KV([['TTL 1 秒', f"{ttl['1 秒'] * 100:.0f}%"], ['TTL 10 秒', f"{ttl['10 秒'] * 100:.0f}%"], ['不过期', f"{ttl['不过期'] * 100:.0f}%"]], ['TTL 10 秒'])),
    step(f"同一个访问序列放到真实的 redis(自己起的实例,maxmemory 1300kb、allkeys-lru):应用侧统计命中率 {rd[0] * 100:.1f}%,redis 自己的 INFO 统计 keyspace_hits {rd[1]}、keyspace_misses {rd[2]},算出来也是 {rd[1] / (rd[1] + rd[2]) * 100:.1f}%(两边一致);内存受限后 evicted_keys = {rd[3]}(被淘汰了这么多个),当前只剩 {rd[4]} 个 key。线上看命中率用 redis 的 keyspace_hits 与 keyspace_misses 就够了,再加 evicted_keys 判断是不是内存不够把热 key 挤掉了。", t=tl(S(4)), done=lidx(S(4), '应用侧统计命中率'), kv=KV([['keyspace_hits / misses', 'redis 自己统计的命中与未命中'], ['evicted_keys', '内存不够时被淘汰的 key 数']], ['evicted_keys'])),
]
A = mkartf('f168', 168, 'Flask,缓存命中率,Redis,Zipf,真实验证,动画演示',
    f'实测缓存命中率:Zipf 访问下容量从 100 增到 5000 命中率 {cap["100"][0] * 100:.0f}% → {cap["5000"][0] * 100:.0f}%、同样容量下均匀随机访问只有 {dist["均匀随机"] * 100:.0f}%、TTL 越短命中率越低(1 秒 {ttl["1 秒"] * 100:.0f}% 到不过期 {ttl["不过期"] * 100:.0f}%)、真实 redis 的 keyspace_hits 与应用侧一致并有 {rd[3]} 个 key 被淘汰。',
    '缓存命中率受什么影响?容量、访问分布、TTL 各自有多大作用?怎么在线上看命中率?这篇用一个有热点的访问序列和真实的 redis,把每个因素的影响量出来。',
    [(f'{cap["100"][0] * 100:.0f}% → {cap["5000"][0] * 100:.0f}%', '缓存容量从 100 增到 5000 时的命中率(Zipf 访问)'), (f'{dist["Zipf(有热点)"] * 100:.0f}% vs {dist["均匀随机"] * 100:.0f}%', '同样容量 500:有热点与均匀随机访问的命中率'), ('keyspace_hits', 'redis 自己统计命中的 INFO 字段')],
    [('容量与命中率', '<p>上一篇:<a href="flask-pool-size.html">连接池大小</a>;下一篇:<a href="flask-large-file-response-performance.html">大文件响应性能</a>。</p><p>访问序列是我生成的 Zipf 分布(固定随机种子),不是真实流量;命中与未命中的耗时(0.05 ms 与 5 ms)是假设值。TTL 一节用模拟时钟,不是真的等了 20 秒。</p>'), ('访问分布', None), ('过期时间', None), ('redis 的命中统计', '<p>redis 是自己在非默认端口起的临时实例,验证完就关闭了。</p>')],
    steps, [ENV_F + '。cachelib SimpleCache、redis-py 8.1.0、自己起的 redis', '没有验证:真实业务流量的访问分布、Flask-Caching 自身的统计接口、缓存穿透与雪崩(第 75 篇看过击穿)、多级缓存、容量按字节计的内存缓存、W-TinyLFU 等更复杂的淘汰策略'], '缓存命中率', panels=[('t', 'term', '实验输出'), ('b', 'bars', '命中率'), ('kv', 'kv', '要点')])
